  const moduleIds = new Set(learning.tajwid.modules.map((item) => item.id));
  extraTajwidModules.forEach((module) => {
    if (!moduleIds.has(module.id)) learning.tajwid.modules.push(module);
  });
  learning.tajwid.modules.forEach((module, index) => { module.number = index + 1; });
  learning.tajwid.totalLessons = learning.tajwid.modules.reduce((sum, module) => sum + module.lessons.length, 0);
